import json

with open('.template.config/template.json') as f:
    data = json.load(f)

# Validate against known .NET template.json schema requirements
issues = []

# Check required fields
required_fields = ['author', 'classifications', 'name', 'shortName', 'identity']
for field in required_fields:
    if field not in data:
        issues.append(f'Missing required field: \"{field}\"')

# Check shortName isn't a reserved name
reserved_short_names = ['build', 'clean', 'restore', 'run', 'test', 'pack', 'publish', 'new', 'list', 'search', 'install', 'uninstall', 'update']
if data.get('shortName', '') in reserved_short_names:
    issues.append(f'shortName \"{data[\"shortName\"]}\" conflicts with a dotnet CLI command')

# Check symbol datatypes
valid_datatypes = ['bool', 'choice', 'float', 'int', 'hex', 'text', 'string']
symbols = data.get('symbols', {})
for name, sym in symbols.items():
    if 'datatype' in sym:
        if sym['datatype'] not in valid_datatypes:
            issues.append(f'Symbol \"{name}\" has invalid datatype: \"{sym[\"datatype\"]}\" (valid: {valid_datatypes})')

for i in issues:
    print(f'- {i}')

if not issues:
    print('No issues found.')
